-- SINH TU DONG boi tools/BuildDiaGioi.py - KHONG SUA TAY. Nguon: Tổng cục Thống kê (NSO) - Bảng chuyển đổi đơn vị hành chính mới-cũ, tệp cập nhật 23/10/2025.
-- BAN NHAP - CHUA CHAY TREN DATABASE CHINH. Chay SAU 008. Nap 'Cu' (63 tinh -> huyen -> xa) va 'Moi' (34 tinh -> xa) + anh xa.
SET ANSI_NULLS ON; SET QUOTED_IDENTIFIER ON; SET ANSI_PADDING ON; SET ANSI_WARNINGS ON; SET ARITHABORT ON; SET CONCAT_NULL_YIELDS_NULL ON; SET NUMERIC_ROUNDABORT OFF; SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @lock int;
EXEC @lock=sys.sp_getapplock @Resource=N'HoTroDuLich.DiaGioi.v1',@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=30000;
IF @lock<0 THROW 51000,N'Không lấy được khóa nạp địa giới.',1;
IF EXISTS (SELECT 1 FROM dbo.DonViHanhChinh) THROW 51002,N'Bảng DonViHanhChinh đã có dữ liệu; không nạp lại.',1;
