INSERT dbo.DonViHanhChinh (Regime,Code,ParentId,[Level],Kind,Name,FullName,NameFolded,Slug,Status,EffectiveFrom,EffectiveTo,SourceName,CheckedOn)
SELECT s.Regime,s.Code,p.Id,s.[Level],s.Kind,s.Name,s.FullName,s.NameFolded,s.Slug,'Active',CASE s.Regime WHEN 'Moi' THEN '2025-07-01' ELSE '1900-01-01' END,CASE s.Regime WHEN 'Cu' THEN '2025-06-30' ELSE NULL END,N'Tổng cục Thống kê (NSO) - Bảng chuyển đổi đơn vị hành chính mới-cũ, tệp cập nhật 23/10/2025','2026-11-10'
FROM #S s LEFT JOIN dbo.DonViHanhChinh p ON p.Regime=s.Regime AND p.Code=s.ParentCode WHERE s.[Level]=1;
IF @@ROWCOUNT<>(SELECT COUNT(*) FROM #S WHERE [Level]=1) THROW 51003,N'Số dòng nạp cấp 1 không khớp (thiếu đơn vị cha).',1;
INSERT dbo.DonViHanhChinh (Regime,Code,ParentId,[Level],Kind,Name,FullName,NameFolded,Slug,Status,EffectiveFrom,EffectiveTo,SourceName,CheckedOn)
SELECT s.Regime,s.Code,p.Id,s.[Level],s.Kind,s.Name,s.FullName,s.NameFolded,s.Slug,'Active',CASE s.Regime WHEN 'Moi' THEN '2025-07-01' ELSE '1900-01-01' END,CASE s.Regime WHEN 'Cu' THEN '2025-06-30' ELSE NULL END,N'Tổng cục Thống kê (NSO) - Bảng chuyển đổi đơn vị hành chính mới-cũ, tệp cập nhật 23/10/2025','2026-11-10'
FROM #S s LEFT JOIN dbo.DonViHanhChinh p ON p.Regime=s.Regime AND p.Code=s.ParentCode WHERE s.[Level]=2;
IF @@ROWCOUNT<>(SELECT COUNT(*) FROM #S WHERE [Level]=2) THROW 51003,N'Số dòng nạp cấp 2 không khớp (thiếu đơn vị cha).',1;
INSERT dbo.DonViHanhChinh (Regime,Code,ParentId,[Level],Kind,Name,FullName,NameFolded,Slug,Status,EffectiveFrom,EffectiveTo,SourceName,CheckedOn)
SELECT s.Regime,s.Code,p.Id,s.[Level],s.Kind,s.Name,s.FullName,s.NameFolded,s.Slug,'Active',CASE s.Regime WHEN 'Moi' THEN '2025-07-01' ELSE '1900-01-01' END,CASE s.Regime WHEN 'Cu' THEN '2025-06-30' ELSE NULL END,N'Tổng cục Thống kê (NSO) - Bảng chuyển đổi đơn vị hành chính mới-cũ, tệp cập nhật 23/10/2025','2026-11-10'
FROM #S s LEFT JOIN dbo.DonViHanhChinh p ON p.Regime=s.Regime AND p.Code=s.ParentCode WHERE s.[Level]=3;
IF @@ROWCOUNT<>(SELECT COUNT(*) FROM #S WHERE [Level]=3) THROW 51003,N'Số dòng nạp cấp 3 không khớp (thiếu đơn vị cha).',1;
