INSERT dbo.DonViChuyenDoi (OldUnitId,NewUnitId,Note)
SELECT o.Id,n.Id,m.Note FROM #M m JOIN dbo.DonViHanhChinh o ON o.Regime='Cu' AND o.Code=m.OldCode JOIN dbo.DonViHanhChinh n ON n.Regime='Moi' AND n.Code=m.NewCode;
IF @@ROWCOUNT<>10571 THROW 51004,N'Số dòng ánh xạ cũ-mới không khớp.',1;
COMMIT TRANSACTION;
